using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Text;using System.Web.Script.Serialization;using System.Windows.Forms;
public sealed class Identity {public int pid;public string startTicks,executable;}
public sealed class FeatureInput {public long at;public string instanceId,launcherRoot,statusFile,stateDirectory;public bool enabled;public Identity client,server;public Dictionary<string,object> config;public Roster roster;}
public sealed class Frame {public AimReader Reader;public Roster Roster;public FeatureInput Input;public long Now;public bool Focus;public IntPtr Window;public Rectangle Bounds;public Scene LastScene;public Scene Scene(bool head,bool esp,int distance,bool exclude){return LastScene=Reader.Read(head,Bounds.Width,Bounds.Height,Roster,esp,distance,exclude);}}
public interface IFeature:IDisposable {string Tick(Frame frame);void Stop();}
public static class Values {public static bool Flag(Dictionary<string,object> c,string key,bool fallback){return c!=null&&c.ContainsKey(key)?Convert.ToBoolean(c[key],CultureInfo.InvariantCulture):fallback;}public static int Number(Dictionary<string,object> c,string key,int fallback){return c!=null&&c.ContainsKey(key)?Convert.ToInt32(c[key],CultureInfo.InvariantCulture):fallback;}public static string Text(Dictionary<string,object> c,string key,string fallback){return c!=null&&c.ContainsKey(key)?Convert.ToString(c[key],CultureInfo.InvariantCulture):fallback;}}
public static class Native {
 [DllImport("kernel32.dll")]public static extern ulong GetTickCount64();[DllImport("user32.dll")]public static extern IntPtr GetForegroundWindow();[DllImport("user32.dll")]public static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);[DllImport("user32.dll")]public static extern bool GetClientRect(IntPtr h,out RECT r);[DllImport("user32.dll")]public static extern bool ClientToScreen(IntPtr h,ref POINT p);[DllImport("user32.dll")]public static extern short GetAsyncKeyState(int key);[DllImport("user32.dll")]static extern uint SendInput(uint count,INPUT[] input,int size);[DllImport("shcore.dll")]public static extern int SetProcessDpiAwareness(int value);
 [StructLayout(LayoutKind.Sequential)]public struct RECT{public int Left,Top,Right,Bottom;}[StructLayout(LayoutKind.Sequential)]public struct POINT{public int X,Y;}[StructLayout(LayoutKind.Sequential)]public struct MOUSEINPUT{public int dx,dy;public uint mouseData,flags,time;public UIntPtr extra;}[StructLayout(LayoutKind.Sequential)]public struct INPUT{public uint type;public MOUSEINPUT mouse;}
 public static bool Down(int key){return (GetAsyncKeyState(key)&0x8000)!=0;}public static bool Move(int x,int y,int pid,string trigger){uint foreground;GetWindowThreadProcessId(GetForegroundWindow(),out foreground);if(foreground!=pid||!AimMath.TriggerHeld(trigger,Down(1),Down(2)))return false;if(x==0&&y==0)return true;return SendInput(1,new[]{new INPUT{type=0,mouse=new MOUSEINPUT{dx=x,dy=y,flags=0x2001}}},Marshal.SizeOf(typeof(INPUT)))==1;}
 public static void Lease(string root,string file,string fields,string name){var directory=Path.GetFullPath(Path.Combine(root,"host/core/local-fun"));Directory.CreateDirectory(directory);var path=Path.Combine(directory,file);var text="[LocalFun]\r\n"+fields+"\r\nTick="+GetTickCount64()+"\r\nPlayerHex="+BitConverter.ToString(Encoding.UTF8.GetBytes(name??"")).Replace("-","").ToLowerInvariant()+"\r\n";var tmp=path+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllText(tmp,text);if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}
}
public sealed class FeatureForm:Form {
 readonly string inputFile;readonly JavaScriptSerializer json=new JavaScriptSerializer();readonly Timer timer=new Timer();readonly Stopwatch clock=Stopwatch.StartNew();readonly IFeature feature=new Feature();AimReader reader;long nextRead,nextStatus;FeatureInput input;string token,last="等待本机角色",state="waiting",phase="read-input";bool closing;
 public FeatureForm(string file){inputFile=file;ShowInTaskbar=false;timer.Interval=25;timer.Tick+=(s,e)=>Tick();timer.Start();FormClosed+=(s,e)=>{timer.Stop();feature.Stop();feature.Dispose();if(reader!=null){reader.M.Process.Dispose();reader.Dispose();}};}
 protected override void SetVisibleCore(bool value){base.SetVisibleCore(false);}
 string Read(string file){using(var f=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var r=new StreamReader(f,Encoding.UTF8,true))return r.ReadToEnd();}
 void Tick(){if(closing)return;try{long now=clock.ElapsedMilliseconds;if(now>=nextRead){nextRead=now+200;input=json.Deserialize<FeatureInput>(Read(inputFile));if(input==null||!input.enabled||(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-input.at>5000||DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-input.at< -5000)){closing=true;Close();return;}if(token==null)token=input.instanceId;if(token!=input.instanceId){closing=true;Close();return;}}
  if(input==null)return;if(input.client==null||input.server==null)throw new Exception("等待本实例服务端和客户端");phase="verify-instance";using(var server=Process.GetProcessById(input.server.pid))ProcessIdentity.Verify(server,Path.Combine(input.launcherRoot,"host/runtime/GameServer/bf4_Server_Final.exe"),input.server.startTicks);if(reader!=null&&(reader.M.Process.HasExited||reader.M.Process.Id!=input.client.pid)){feature.Stop();reader.M.Process.Dispose();reader.Dispose();reader=null;}
  if(reader==null){var p=Process.GetProcessById(input.client.pid);var expected=Path.GetFullPath(Path.Combine(input.launcherRoot,"host/mods/client/bf4_no_drm.exe"));try{ProcessIdentity.Verify(p,expected,input.client.startTicks);if(!string.Equals(Path.GetFullPath(input.client.executable),expected,StringComparison.OrdinalIgnoreCase))throw new Exception("本实例客户端身份不匹配");phase="open-client";reader=new AimReader(p);}catch{p.Dispose();throw;}}
  var window=Native.GetForegroundWindow();uint foreground;Native.GetWindowThreadProcessId(window,out foreground);var frame=new Frame{Reader=reader,Roster=input.roster,Input=input,Now=now,Window=window,Focus=foreground==reader.M.Process.Id,Bounds=new Rectangle(0,0,1920,1080)};
  Native.RECT rect;if(frame.Focus&&Native.GetClientRect(window,out rect)){var origin=new Native.POINT();Native.ClientToScreen(window,ref origin);frame.Bounds=new Rectangle(origin.X,origin.Y,rect.Right,rect.Bottom);}phase="run-feature";last=feature.Tick(frame);state=frame.LastScene!=null&&frame.LastScene.Ready?"applied":"waiting";
 }catch(Exception e){last=e.Message;state="error";feature.Stop();}
 if(input!=null&&clock.ElapsedMilliseconds>=nextStatus){nextStatus=clock.ElapsedMilliseconds+500;try{var p=input.statusFile;var tmp=p+".tmp";File.WriteAllText(tmp,json.Serialize(new{apiVersion=1,clientBuild=Mem.ClientBuild,instanceId=token,at=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),message=last,state=state,phase=phase,pid=Process.GetCurrentProcess().Id,clientPid=input.client==null?0:input.client.pid,serverPid=input.server==null?0:input.server.pid}));if(File.Exists(p))File.Replace(tmp,p,null);else File.Move(tmp,p);}catch{}}
 }
}
public static class App {public const string Version="1.2.0";[STAThread]public static void Main(string[] args){if(args.Length==1&&args[0]=="--self-test"){try{if(!Mem.AcceptsClientHash("0365a62f197d4544b5326b82a682d77af542e973cb3d9cb6ae582cd543fae2d0")||Mem.AcceptsClientHash(new string('0',64)))throw new Exception("V2 build policy");if(!AimMath.TriggerHeld("ads",false,true)||AimMath.TriggerHeld("ads",true,false)||!Roster.ValidEndpoint("127.0.0.1:25205"))throw new Exception("Runtime policy");Feature.Test();Console.WriteLine("PASS");}catch{Environment.ExitCode=1;}return;}if(args.Length!=2||args[0]!="--input"){Environment.ExitCode=2;return;}try{Native.SetProcessDpiAwareness(2);}catch{}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new FeatureForm(args[1]));}}
